SELECT setval(pg_get_serial_sequence('colecciones','id'), (SELECT MAX(id) FROM colecciones));

-- ── 4. artistas ──────────────────────────────────────────────
SELECT setval(pg_get_serial_sequence('artistas','id'), (SELECT MAX(id) FROM artistas));

