  (53,'impulso','Impulso',NULL,NULL,NULL,'Levi Nazaret','https://pub-580903d2b97f4b4e8810af8c9432d80a.r2.dev/peliculas/impulso/poster.jpg','https://pub-580903d2b97f4b4e8810af8c9432d80a.r2.dev/peliculas/impulso/video.mp4','https://www.youtube.com/embed/jIjGX8FVATw','https://generacionmaldita.com/wp-content/uploads/2026/05/5-IMpulso-Levi-nazaret.gif','https://generacionmaldita.com/cortometraje/impulso/'),
  (54,'higiene-de-sueno','Higiene del sueño','"Higiene del sueño" es un corto animado que sigue a un personaje en su camino hacia una mejor calidad de sueño. Con un estilo de animación colorido y una trama entretenida, este corto explora la importancia de tener una rutina de sueño saludable. A lo largo de su aventura, el personaje aprende acerca de los hábitos que pueden mejorar la calidad del sueño, como establecer un horario regular para acostarse y levantarse, limitar la exposición a pantallas antes de dormir y crear un ambiente relajante en el dormitorio. Este corto es una excelente herramienta para enseñar a los niños y adultos jóvenes acerca de la importancia de la higiene del sueño. Con un mensaje divertido y accesible, "Higiene del sueño" muestra de manera clara y concisa cómo tener una rutina de sueño saludable puede mejorar la vida de una persona. Además, el corto también…',NULL,NULL,'Generación Maldita','https://pub-580903d2b97f4b4e8810af8c9432d80a.r2.dev/peliculas/higiene-de-sueno/poster.jpg','https://pub-580903d2b97f4b4e8810af8c9432d80a.r2.dev/peliculas/higiene-de-sueno/video.mp4','https://www.youtube.com/embed/YezpFPkpMaQ','https://generacionmaldita.com/wp-content/uploads/2026/05/swiper-image.png','https://generacionmaldita.com/cortometraje/higiene-de-sueno/'),
  (55,'genesis-animatic','Génesis (ANIMATIC)',NULL,NULL,NULL,'Yamii Velasco','https://pub-580903d2b97f4b4e8810af8c9432d80a.r2.dev/peliculas/genesis-animatic/poster.jpg','https://pub-580903d2b97f4b4e8810af8c9432d80a.r2.dev/peliculas/genesis-animatic/video.mp4','https://www.youtube.com/embed/cUis4mmof-s','https://generacionmaldita.com/wp-content/uploads/2026/05/15-Genesis-YamiiVelasco.png','https://generacionmaldita.com/cortometraje/genesis-animatic/'),
