  (71,'curvilinea','Curvilínea',NULL,NULL,NULL,'Manuel Tell','https://pub-580903d2b97f4b4e8810af8c9432d80a.r2.dev/peliculas/curvilinea/poster.jpg','https://pub-580903d2b97f4b4e8810af8c9432d80a.r2.dev/peliculas/curvilinea/video.mp4','https://www.youtube.com/embed/-w4HlnPmJvc','https://generacionmaldita.com/wp-content/uploads/2026/05/1-curvilinea-Manuel-Tell.png','https://generacionmaldita.com/cortometraje/curvilinea/'),
  (72,'cuco','Cuco',NULL,NULL,NULL,'Alexander Ortiz','https://pub-580903d2b97f4b4e8810af8c9432d80a.r2.dev/peliculas/cuco/poster.jpg','https://pub-580903d2b97f4b4e8810af8c9432d80a.r2.dev/peliculas/cuco/video.mp4','https://www.youtube.com/embed/QFlKonixPkU','https://generacionmaldita.com/wp-content/uploads/2026/05/2-Cuco-Alexander-ortiz.jpg','https://generacionmaldita.com/cortometraje/cuco/'),
  (73,'control-mental','Control Mental','Una criatura ejerce un control absoluto sobre la mente de otra en un juego de dominación que borra los límites entre voluntad y obediencia. Un corto que explora el poder como adicción y la identidad como territorio conquistable.','2021','3m 5s','Creado por: Satan Orbis; Ilustración por: AbadMONO','https://pub-580903d2b97f4b4e8810af8c9432d80a.r2.dev/peliculas/control-mental/poster.jpg','https://pub-580903d2b97f4b4e8810af8c9432d80a.r2.dev/peliculas/control-mental/video.mp4','https://www.youtube.com/embed/LgI4FfwI3mA','https://generacionmaldita.com/wp-content/uploads/2026/05/7-Control-mental-mono.jpg','https://generacionmaldita.com/cortometraje/control-mental/'),
  (74,'cazando-perros','Cazando perros','Un astronauta hambriento se embarca en una aventura espacial con su fiel compañero Bot, lamentablemente cazar su comida no será fácil para él.',NULL,NULL,'Vramz','https://pub-580903d2b97f4b4e8810af8c9432d80a.r2.dev/peliculas/cazando-perros/poster.jpg','https://pub-580903d2b97f4b4e8810af8c9432d80a.r2.dev/peliculas/cazando-perros/video.mp4','https://www.youtube.com/embed/5xW9d8K5Wgs','https://generacionmaldita.com/wp-content/uploads/2026/05/1-cazando-Perros-ilustratio_Vramz.jpg','https://generacionmaldita.com/cortometraje/cazando-perros/'),
  (75,'chi-no-wadachi-fan-animation','Chi no wadachi Fan Animation','Basado en el manga de Shūzō Oshimi Sobre la extraña relación de una madre y su hijo.',NULL,NULL,'Adri Jalón','https://pub-580903d2b97f4b4e8810af8c9432d80a.r2.dev/peliculas/chi-no-wadachi-fan-animation/poster.jpg','https://pub-580903d2b97f4b4e8810af8c9432d80a.r2.dev/peliculas/chi-no-wadachi-fan-animation/video.mp4','https://www.youtube.com/embed/_WYzgrjazgU','https://generacionmaldita.com/wp-content/uploads/2026/05/2d-Chi-No-Wadachi-Adri-Jalon.jpg','https://generacionmaldita.com/cortometraje/chi-no-wadachi-fan-animation/'),
